-- pipeline/decide-item
-- A reviewer dismisses a candidate or marks it done. Only a candidate still waiting can change.
--
-- Parameters, with the example values used to render this file:
--   $1 = "dismissed"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--   $3 = "0199c8a0-0000-7000-8000-00000000000a"
--   $4 = "new"
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

update "feed_items"
set "status" = $1, "decided_by" = $2, "decided_at" = now()
where ("feed_items"."id" = $3
  and "feed_items"."status" = $4)
returning "id";
